// Health pages: HTML for the open-issue index and for one issue. Pure functions of the stored rows.
const TIMEZONE = 'America/New_York';
const esc = (v) => String(v === null || v === undefined ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const when = (iso) => (iso ? DateTime.fromISO(String(iso)).setZone(TIMEZONE).toFormat('yyyy-LL-dd HH:mm') : '');
const tierRank = (t) => ({ H1: 1, H2: 2, H3: 3, M1: 4, M2: 5, M3: 6, L: 7 }[t] || 8);
const parse = (s) => { try { return JSON.parse(s || '{}'); } catch (e) { return {}; } };
const safeUrl = (u) => (/^https?:\/\//i.test(String(u || '')) ? String(u) : '');

function page(title, body) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(title)}</title>
<style>
body{font:15px/1.45 system-ui,sans-serif;margin:0 auto;max-width:960px;padding:16px;color:#1d1d1f;background:#fff}
h1{font-size:1.3em}h2{font-size:1.1em;margin-top:1.6em}table{border-collapse:collapse;width:100%}
td,th{border-bottom:1px solid #ddd;padding:6px 8px;text-align:left;vertical-align:top}
th{font-weight:600}.t{font-weight:700;white-space:nowrap}.H1,.H2,.H3{color:#b00020}.M1,.M2,.M3{color:#a35a00}.L{color:#555}
.muted{color:#666}pre{white-space:pre-wrap;word-break:break-word;background:#f5f5f7;padding:8px}
@media (prefers-color-scheme:dark){body{background:#111;color:#eee}td,th{border-color:#333}pre{background:#222}.muted{color:#aaa}}
</style></head><body>${body}</body></html>`;
}

function renderIndex(rows, now) {
  const issues = rows.filter((r) => r && r.fingerprint);
  const open = issues.filter((r) => r.status === 'open' || r.status === 'accepted')
    .sort((a, b) => tierRank(a.tier) - tierRank(b.tier) || String(a.first_seen).localeCompare(String(b.first_seen)));
  const weekAgo = DateTime.fromISO(now).minus({ days: 7 });
  const resolved = issues.filter((r) => r.status === 'resolved' && r.resolved_at && DateTime.fromISO(String(r.resolved_at)) >= weekAgo)
    .sort((a, b) => String(b.resolved_at).localeCompare(String(a.resolved_at)));
  const titleOf = new Map(issues.map((r) => [r.fingerprint, r.title]));
  const row = (r, extra) => `<tr><td class="t ${esc(r.tier)}">${esc(r.tier)}</td>
<td><a href="issue?fp=${esc(r.fingerprint)}">${esc(r.title)}</a><div class="muted">${esc([r.cluster, r.subject].filter(Boolean).join(', '))}${
  r.root_cause_fp ? ` &middot; likely caused by ${esc(titleOf.get(r.root_cause_fp) || r.root_cause_fp)}` : ''}</div></td>
<td>${extra}</td></tr>`;
  const openRows = open.map((r) => row(r, `${esc(r.status === 'accepted' ? 'accepted (silenced)' : 'open')}<div class="muted">since ${esc(when(r.first_seen))}</div>`)).join('');
  const resolvedRows = resolved.map((r) => row(r, `resolved ${esc(when(r.resolved_at))}`)).join('');
  return page('Cluster health', `<h1>Cluster health</h1>
<p class="muted">As of ${esc(when(now))} ${esc(TIMEZONE)}. ${open.length} open or accepted, ${resolved.length} resolved in the last 7 days.</p>
<h2>Open</h2>${open.length ? `<table><tr><th>Tier</th><th>Problem</th><th>State</th></tr>${openRows}</table>` : '<p>Nothing open.</p>'}
<h2>Resolved in the last 7 days</h2>${resolved.length ? `<table><tr><th>Tier</th><th>Problem</th><th>When</th></tr>${resolvedRows}</table>` : '<p>None.</p>'}`);
}

function renderDiagnosis(json) {
  const d = parse(json);
  if (!d || !d.summary) return '<p class="muted">Not diagnosed.</p>';
  const list = (xs, f) => (Array.isArray(xs) && xs.length ? `<ul>${xs.map((x) => `<li>${f(x)}</li>`).join('')}</ul>` : '<p class="muted">None.</p>');
  const rc = d.root_cause || {};
  const fix = d.fix || {};
  return `<p><b>${esc(d.summary)}</b></p>
<p>Root cause (${esc(rc.confidence || 'unknown')}): ${esc(rc.statement || '')}${rc.capability ? ` <span class="muted">[${esc(rc.capability)}]</span>` : ''}</p>
${d.impact && d.impact.blast_radius ? `<p>Blast radius: ${esc(d.impact.blast_radius)}</p>` : ''}
<h3>Evidence</h3>${list(d.evidence, (e) => `<span class="muted">${esc(e.kind)}</span> ${esc(e.tool)} ${esc(e.args)}<pre>${esc(e.excerpt)}</pre>`)}
<h3>Ruled out</h3>${list(d.ruled_out, (r) => `${esc(r.hypothesis)}: ${esc(r.refuted_by)}`)}
${Array.isArray(d.unexplained_alerts) && d.unexplained_alerts.length ? `<h3>Not explained</h3>${list(d.unexplained_alerts, esc)}` : ''}
<h3>Fix</h3>${fix.where ? `<p>Where: ${esc(fix.where)}</p>` : ''}${Array.isArray(fix.steps) && fix.steps.length ? `<ol>${fix.steps.map((s) => `<li>${esc(s)}</li>`).join('')}</ol>` : '<p class="muted">No steps.</p>'}
${d.verify_after_fix ? `<p>Verify after the fix: ${esc(d.verify_after_fix)}</p>` : ''}`;
}

function renderIssue(issue, events, related) {
  if (!issue) return null;
  const ann = parse(issue.annotations_json);
  const labels = parse(issue.labels_json);
  const runbook = safeUrl(ann.runbook_url);
  const facts = [
    ['State', issue.status === 'accepted' ? 'accepted (silenced in Alertmanager)' : issue.status],
    ['Tier', issue.tier], ['Capability', issue.capability], ['Cluster', issue.cluster], ['Subject', issue.subject],
    ['Severity', issue.severity], ['First seen', when(issue.first_seen)], ['Last seen', when(issue.last_seen)],
    ['Resolved', when(issue.resolved_at)], ['Runs seen', issue.runs_seen], ['Recurrences', issue.recurrences],
    ['Alerts in this issue', issue.alert_count],
  ].filter(([, v]) => v !== '' && v !== null && v !== undefined);
  const root = related.find((r) => r.fingerprint === issue.root_cause_fp);
  const attached = related.filter((r) => r.root_cause_fp === issue.fingerprint && r.status === 'open');
  const history = [...events].sort((a, b) => String(b.ts).localeCompare(String(a.ts))).slice(0, 100);
  return page(issue.title, `<p><a href="issues">&larr; All issues</a></p>
<h1><span class="${esc(issue.tier)}">[${esc(issue.tier)}]</span> ${esc(issue.title)}</h1>
${ann.description && ann.description !== issue.title ? `<p>${esc(ann.description)}</p>` : ''}
${runbook ? `<p><a href="${esc(runbook)}">Runbook</a></p>` : ''}
${root ? `<p>Likely a consequence of <a href="issue?fp=${esc(root.fingerprint)}">${esc(root.title)}</a>.</p>` : ''}
${attached.length ? `<h2>Attached issues (likely consequences)</h2><ul>${attached.map((r) => `<li><a href="issue?fp=${esc(r.fingerprint)}">${esc(r.title)}</a> <span class="muted">${esc(r.subject)}</span></li>`).join('')}</ul>` : ''}
<h2>State</h2><table>${facts.map(([k, v]) => `<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</table>
<h2>Diagnosis</h2>${renderDiagnosis(issue.diagnosis_json)}
<h2>History</h2>${history.length ? `<table><tr><th>When</th><th>Transition</th><th>Detail</th></tr>${history.map((e) => `<tr><td>${esc(when(e.ts))}</td><td>${esc(e.transition)}</td><td>${esc(e.detail)}</td></tr>`).join('')}</table>` : '<p class="muted">No events.</p>'}
<h2>Labels</h2><pre>${esc(JSON.stringify(labels, null, 2))}</pre>
<p class="muted">Fingerprint ${esc(issue.fingerprint)}</p>`);
}

const notFound = () => page('Not found', '<h1>Not found</h1><p><a href="issues">All issues</a></p>');


const rows = $('Get Issues For Index').all().map((i) => i.json);
const failed = rows.find((r) => r.error);
if (failed) return [{ json: { code: 503, html: page('Cluster health', '<h1>Cluster health</h1><p>No data yet: the Health Triage workflow has not run.</p>') } }];
return [{ json: { code: 200, html: renderIndex(rows, DateTime.now().toUTC().toISO()) } }];

