const fp = String(($('Issue Page').first().json.query || {}).fp || '');
const rows = $('Get Issues For Page').all().map((i) => i.json).filter((r) => r.fingerprint);
const issue = /^[0-9a-f]{40}$/.test(fp) ? rows.find((r) => r.fingerprint === fp) : null;
if (!issue) return [{ json: { code: 404, html: notFound() } }];
const events = $('Get Events').all().map((i) => i.json).filter((e) => e.fingerprint === fp);
return [{ json: { code: 200, html: renderIssue(issue, events, rows) } }];
